from lib import *
L = lambda *a, **k: lesson(44, "A1", *a, **k)
V = "verb"
N = "noun"
A = "adjective"
L(1, "Який він за характером?", "Описати людину кількома словами.",
 "Характер описуємо через is + прикметник: He is shy. She is polite. Shy — сором'язливий, polite — ввічливий, rude — грубий, honest — чесний, lazy — лінивий. Рівно ті ж слова підходять і до мене: I'm shy.",
 [W("shy", "/ʃaɪ/", A, "сором'язливий", "My brother is shy.", "Мій брат сором'язливий."),
  W("polite", "/pəˈlaɪt/", A, "ввічливий", "She is always polite.", "Вона завжди ввічлива."),
  W("rude", "/ruːd/", A, "грубий", "Don't be rude.", "Не будьте грубі."),
  W("honest", "/ˈɒnɪst/", A, "чесний", "He is an honest man.", "Він чесна людина."),
  W("lazy", "/ˈleɪzi/", A, "лінивий", "I'm lazy on Sundays.", "По неділях я лінивий.")],
 [li("Can you describe your brother?", "Повторимо. Він високий, кучерявий. Що відповісти?", ["He is tall and has curly hair.", "He tall and curly hair is.", "He has tall and is curly."], "Is tall, has curly hair."),
  mt([("shy", "сором'язливий"), ("polite", "ввічливий"), ("rude", "грубий"), ("honest", "чесний"), ("lazy", "лінивий")], "Слова про характер."),
  liu("My brother is shy.", "Прослухайте. Який брат?", ["Сором'язливий", "Грубий", "Лінивий"], "Shy."),
  liu("She is always polite.", "Прослухайте. Яка вона?", ["Завжди ввічлива", "Завжди сумна", "Завжди зайнята"], "Polite."),
  liu("He is an honest man.", "Прослухайте. Який чоловік?", ["Чесний", "Лінивий", "Грубий"], "Honest."),
  fb("My brother is ___. He doesn't talk to new people.", ["shy", "rude", "lazy"], "Shy."),
  fb("Don't be ___!", ["rude", "polite", "honest"], "Don't be rude."),
  fb("He ___ an honest man.", ["is", "has", "does"], "He is."),
  mc("Яке слово описує людину, що не любить працювати?", ["lazy", "polite", "shy"], "Lazy."),
  bs("Вона завжди ввічлива.", ["She", "is", "always", "polite"], ["has", "rude"], "She is always polite."),
  tr("Мій брат сором'язливий.", ["My brother is shy"], "My brother is shy."),
  li("Is your sister shy?", "Ні, вона відкрита. Що відповісти?", ["No, she isn't.", "No, she doesn't.", "No, she hasn't."], "No, she isn't.")])
L(2, "Добрі риси", "Сказати добре про людину.",
 "Generous — щедрий, helpful — той, хто охоче допомагає, patient — терплячий, calm — спокійний, brave — сміливий. Приклад: He is generous. She is patient with children. Прийменник: patient with — терплячий до.",
 [W("generous", "/ˈdʒenərəs/", A, "щедрий", "My uncle is generous.", "Мій дядько щедрий."),
  W("helpful", "/ˈhelpfl/", A, "готовий допомогти", "Our neighbour is helpful.", "Наш сусід охоче допомагає."),
  W("patient", "/ˈpeɪʃnt/", A, "терплячий", "She is patient with children.", "Вона терпляча з дітьми."),
  W("calm", "/kɑːm/", A, "спокійний", "He stays calm.", "Він залишається спокійним."),
  W("brave", "/breɪv/", A, "сміливий", "The firefighter is brave.", "Пожежник сміливий.")],
 [fb("Don't be ___!", ["rude", "generous", "calm"], "Rude.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("generous", "щедрий"), ("helpful", "готовий допомогти"), ("patient", "терплячий"), ("calm", "спокійний"), ("brave", "сміливий")], "Добрі риси."),
  liu("My uncle is generous.", "Прослухайте. Який дядько?", ["Щедрий", "Лінивий", "Грубий"], "Generous."),
  liu("She is patient with children.", "Прослухайте. З ким вона терпляча?", ["З дітьми", "З колегами", "З сусідами"], "With children."),
  liu("The firefighter is brave.", "Прослухайте. Який пожежник?", ["Сміливий", "Спокійний", "Щедрий"], "Brave."),
  fb("Our neighbour is very ___. He always helps.", ["helpful", "lazy", "rude"], "Helpful."),
  fb("She is patient ___ children.", ["with", "at", "of"], "Patient with."),
  fb("He is always ___ and never shouts.", ["calm", "rude", "lazy"], "Calm."),
  mc("Яке слово означає «спокійний»?", ["calm", "brave", "generous"], "Calm."),
  bs("Вона терпляча з дітьми.", ["She", "is", "patient", "with", "children"], ["has", "at"], "She is patient with children."),
  tr("Мій дядько щедрий.", ["My uncle is generous"], "My uncle is generous."),
  li("Is your neighbour helpful?", "Так, дуже. Що відповісти?", ["Yes, he is very helpful.", "Yes, he very helpful.", "Yes, he has helpful."], "Yes, he is very helpful.")])
L(3, "Працьовитий і балакучий", "Описати риси на роботі й у спілкуванні.",
 "Hard-working — працьовитий, talkative — балакучий, confident — впевнений, curious — допитливий, reliable — надійний. Приклад: Our manager is reliable. My little brother is curious: he asks a lot of questions.",
 [W("hard-working", "/ˌhɑːd ˈwɜːkɪŋ/", A, "працьовитий", "She is hard-working.", "Вона працьовита."),
  W("talkative", "/ˈtɔːkətɪv/", A, "балакучий", "My sister is talkative.", "Моя сестра балакуча."),
  W("confident", "/ˈkɒnfɪdənt/", A, "впевнений", "He is confident.", "Він упевнений у собі."),
  W("curious", "/ˈkjʊəriəs/", A, "допитливий", "Children are curious.", "Діти допитливі."),
  W("reliable", "/rɪˈlaɪəbl/", A, "надійний", "Our manager is reliable.", "Наш менеджер надійний.")],
 [li("Is your neighbour helpful?", "Повторимо. Так. Що відповісти?", ["Yes, he is.", "Yes, he does.", "Yes, he has."], "Yes, he is."),
  mt([("hard-working", "працьовитий"), ("talkative", "балакучий"), ("confident", "впевнений"), ("curious", "допитливий"), ("reliable", "надійний")], "Риси характеру."),
  liu("She is hard-working.", "Прослухайте. Яка вона?", ["Працьовита", "Лінива", "Сором'язлива"], "Hard-working."),
  liu("My sister is very talkative.", "Прослухайте. Яка сестра?", ["Балакуча", "Мовчазна", "Грубувата"], "Talkative."),
  liu("Our manager is reliable.", "Прослухайте. Який менеджер?", ["Надійний", "Грубий", "Лінивий"], "Reliable."),
  fb("My sister talks a lot. She is ___.", ["talkative", "shy", "calm"], "Talkative."),
  fb("Children are ___. They ask a lot of questions.", ["curious", "lazy", "rude"], "Curious."),
  fb("He is very ___. He believes in himself.", ["confident", "shy", "lazy"], "Confident."),
  mc("Яке слово описує людину, на яку можна покластися?", ["reliable", "talkative", "curious"], "Reliable."),
  bs("Наш менеджер надійний.", ["Our", "manager", "is", "reliable"], ["are", "lazy"], "Our manager is reliable."),
  tr("Вона працьовита.", ["She is hard-working", "She's hard-working"], "She is hard-working."),
  li("Is your colleague talkative?", "Ні, він мовчазний. Що відповісти?", ["No, he is quiet.", "No, he quiet is.", "No, he has quiet."], "No, he is quiet.")])
L(4, "Дуже, трохи, надто", "Додати відтінок до характеру.",
 "Перед прикметником: very — «дуже», quite — «досить», a bit — «трохи», too — «занадто». He is quite shy. She is a bit lazy. He talks too much. Not very — «не дуже»: She isn't very patient.",
 [W("quite", "/kwaɪt/", "adverb", "досить", "He is quite shy.", "Він досить сором'язливий."),
  W("a bit", "/ə ˈbɪt/", "phrase", "трохи", "She is a bit lazy.", "Вона трохи лінива."),
  W("extremely", "/ɪkˈstriːmli/", "adverb", "надзвичайно", "She is extremely patient.", "Вона надзвичайно терпляча."),
  W("not very", "/ˌnɒt ˈveri/", "phrase", "не дуже", "She isn't very patient.", "Вона не дуже терпляча."),
  W("rather", "/ˈrɑːðə/", "adverb", "досить, доволі", "He is rather quiet.", "Він доволі мовчазний.")],
 [fb("Our manager is ___.", ["reliable", "talkative", "rude"], "Reliable.", "Повторимо. Оберіть слово, якого бракує"),
  mt([("quite", "досить"), ("a bit", "трохи"), ("extremely", "надзвичайно"), ("not very", "не дуже"), ("rather", "доволі")], "Слова, що змінюють значення."),
  liu("He is quite shy.", "Прослухайте. Який він?", ["Досить сором'язливий", "Дуже грубий", "Трохи лінивий"], "Quite shy."),
  liu("She is a bit lazy.", "Прослухайте. Яка вона?", ["Трохи лінива", "Дуже лінива", "Працьовита"], "A bit lazy."),
  liu("He talks too much.", "Прослухайте. Що каже людина?", ["Він говорить занадто багато", "Він мало говорить", "Він добре говорить"], "Too much."),
  fb("She is ___ shy. She never talks to new people.", ["very", "a bit", "not very"], "Very — дуже."),
  fb("She isn't ___ patient.", ["very", "too", "quite not"], "Not very."),
  fb("He is ___ honest.", ["really", "too", "a bit of"], "Really honest."),
  mc("Яке речення означає «Він говорить занадто багато»?", ["He talks too much.", "He talks very much too.", "He too talks much."], "Too much."),
  bs("Він досить сором'язливий.", ["He", "is", "quite", "shy"], ["has", "too"], "He is quite shy."),
  tr("Вона не дуже терпляча.", ["She isn't very patient", "She is not very patient"], "She isn't very patient."),
  li("Is your sister shy?", "Трохи. Що відповісти?", ["She is a bit shy.", "She a bit is shy.", "She is bit a shy."], "She is a bit shy.")])
L(5, "Який він насправді?", "Спитати про характер і відповісти.",
 "Увага! What is he like? — про характер: He is kind and polite. What does he look like? — про зовнішність: He is tall. Також: get on with — ладнати з кимось: I get on with my brother. Personality — характер, особистість.",
 [W("what is he like", "/ˌwɒt ɪz hi ˈlaɪk/", "phrase", "який він (за характером)", "What is your boss like?", "Який у вас начальник?"),
  W("personality", "/ˌpɜːsəˈnæləti/", N, "характер, особистість", "She has a great personality.", "У неї чудовий характер."),
  W("get on with", "/ˌɡet ˈɒn wɪð/", "phrase", "ладнати з", "I get on with my brother.", "Я ладнаю з братом."),
  W("trust", "/trʌst/", V, "довіряти", "I trust my friend.", "Я довіряю своєму другові."),
  W("sense of humour", "/ˌsens əv ˈhjuːmə/", "phrase", "почуття гумору", "He has a good sense of humour.", "У нього гарне почуття гумору.")],
 [li("Is she shy?", "Повторимо. Трохи. Що відповісти?", ["She is a bit shy.", "She a bit is shy.", "She is bit a shy."], "A bit shy."),
  mt([("what is he like", "який він (характер)"), ("personality", "характер"), ("get on with", "ладнати з"), ("trust", "довіряти"), ("sense of humour", "почуття гумору")], "Слова про характер."),
  liu("What is your boss like?", "Прослухайте. Про що питають?", ["Про характер начальника", "Про зовнішність начальника", "Про вік начальника"], "Character."),
  liu("I get on with my brother.", "Прослухайте. Що каже людина?", ["Вона ладнає з братом", "Вона свариться з братом", "Вона не бачить брата"], "Gets on."),
  liu("He has a good sense of humour.", "Прослухайте. Що в нього гарне?", ["Почуття гумору", "Голос", "Зовнішність"], "Sense of humour."),
  fb("What is she ___?", ["like", "look", "likes"], "What is she like?"),
  fb("I ___ my friend.", ["trust", "get on", "personality"], "Trust — довіряти."),
  fb("I get ___ with my brother.", ["on", "in", "at"], "Get on with."),
  mc("Як спитати про характер?", ["What is she like?", "What does she like?", "What does she look like?"], "What is she like?"),
  bs("У неї чудовий характер.", ["She", "has", "a", "great", "personality"], ["is", "have"], "She has a great personality."),
  tr("Я довіряю своєму другові.", ["I trust my friend"], "I trust my friend."),
  li("What is your boss like?", "Він добрий і терплячий. Що відповісти?", ["He is kind and patient.", "He has kind and patient.", "He looks like kind."], "Is kind and patient.")])
L(6, "Повторення: характер", "Закріпити слова про характер.",
 "Нових слів немає. Повторюємо: прикметники характеру (shy, polite, generous, patient, reliable, hard-working…), very / quite / a bit / too, і різницю What is he like? та What does he look like?",
 [],
 [li("What is your sister like?", "Вона добра й працьовита. Що відповісти?", ["She is kind and hard-working.", "She has kind and hard-working.", "She looks like kind."], "Is kind and hard-working."),
  fb("He is ___ shy. He never talks to new people.", ["very", "too much", "bit"], "Very shy."),
  fb("What does he ___ like? — He is tall.", ["look", "is", "like"], "What does he look like?"),
  tr("Я довіряю своєму другові.", ["I trust my friend"], "I trust my friend."),
  liu("She is quite shy, but she has a great sense of humour.", "Прослухайте. Що в неї чудове?", ["Почуття гумору", "Зовнішність", "Голос"], "Sense of humour."),
  mc("Яке запитання про характер?", ["What is he like?", "What does he look like?", "Where is he from?"], "What is he like?"),
  bs("Вона не дуже терпляча.", ["She", "isn't", "very", "patient"], ["is", "too"], "She isn't very patient."),
  fb("My uncle is ___. He gives presents to everyone.", ["generous", "rude", "lazy"], "Generous."),
  tr("Наш менеджер надійний.", ["Our manager is reliable"], "Our manager is reliable."),
  liu("My sister is talkative and my brother is quiet.", "Прослухайте. Хто мовчазний?", ["Брат", "Сестра", "Обоє"], "Brother."),
  fb("I get ___ with my colleagues.", ["on", "in", "at"], "Get on with."),
  li("Is he honest?", "Так, дуже. Що відповісти?", ["Yes, he is very honest.", "Yes, he very honest.", "Yes, he has honest."], "Yes, he is very honest.")],
 review=True)
